[CmdletBinding()]
param(
    [Parameter(Mandatory)]
    [string]$ExpectedRepositoryRoot
)

$ErrorActionPreference = 'Stop'
$utf8 = [Text.UTF8Encoding]::new($false, $true)
$root = [IO.Path]::GetFullPath($ExpectedRepositoryRoot)
$workingRoot = (Resolve-Path -LiteralPath '.').Path
if ($root -cne $workingRoot) { throw 'The caller must be at the expected repository root.' }
$topLevel = git rev-parse --show-toplevel
if ($LASTEXITCODE -ne 0 -or [IO.Path]::GetFullPath($topLevel) -cne $root) { throw 'Git resolved a different repository root.' }

$sessionJson = entire session current --json
if ($LASTEXITCODE -ne 0) { throw 'Could not verify the active Entire session.' }
$session = $sessionJson | ConvertFrom-Json
if ($session.resolution -cnotin @('caller-env', 'ancestry')) { throw "The session is not caller-verified ($($session.resolution))." }

$base = git merge-base origin/main HEAD
if ($LASTEXITCODE -ne 0 -or !$base) { throw 'Could not resolve the branch base.' }
$branch = git branch --show-current
if ($LASTEXITCODE -ne 0 -or $branch -cne 'codex/sync-agent-instructions') { throw "Unexpected branch ($branch)." }

$source = 'C:\Users\lcvle\lcv-workspace\AGENTS.md'
$masterBytes = [IO.File]::ReadAllBytes($source)
$masterDigest = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($masterBytes))
if ($masterDigest -cne '519F83F7BCAA519C141E361F7D6D713986331EB8513CEA1B365F92EC247CA585') { throw 'The authorized workspace master changed.' }
$master = $utf8.GetString($masterBytes)
$boundary = '* Never secrets, credentials, unnecessary exploit payloads, or weaponization details in pull-request comments.'
$boundaryPattern = '(?m)^' + [regex]::Escape($boundary) + '(?=\r?$)'
$masterMatch = [regex]::Matches($master, $boundaryPattern)
if ($masterMatch.Count -ne 1) { throw 'The workspace master has no unique terminal review boundary.' }
$approvedPrefix = $master.Substring(0, $masterMatch[0].Index + $masterMatch[0].Length)

$paths = @((Join-Path $root 'AGENTS.md'), (Join-Path $root 'CLAUDE.md'))
foreach ($path in $paths) {
    $item = Get-Item -LiteralPath $path -Force
    if ($item.PSIsContainer -or $item.LinkType -or ($item.Attributes -band [IO.FileAttributes]::ReadOnly)) { throw "Unexpected Git instruction file attributes: $path" }
}
$priorBytes = [IO.File]::ReadAllBytes($paths[0])
$otherBytes = [IO.File]::ReadAllBytes($paths[1])
if ([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($priorBytes)) -cne [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($otherBytes))) { throw 'Existing repository instruction files differ. Inspect both before writing.' }
$previous = $utf8.GetString($priorBytes)
$hasBom = ($previous.Length -gt 0 -and $previous[0] -eq [char]0xFEFF)
if ($hasBom) { $previous = $previous.Substring(1) }
if (!$previous.StartsWith("---", [StringComparison]::Ordinal)) { throw 'The repository instruction file has unexpected encoding or front matter.' }

$matches = [regex]::Matches($previous, $boundaryPattern)
if ($matches.Count -ne 1) { throw 'The repository has no unique terminal review boundary.' }
$previousEnd = $matches[0].Index + $matches[0].Length
$previousPrefix = $previous.Substring(0, $previousEnd)
$sourceSuffix = $previous.Substring($previousEnd)
if ($previousPrefix -match '(?m)^[ \t]*<!-- entire-agent:(?:begin|end) -->[ \t]*\r?$') { throw 'An Entire-managed block within the master prefix needs position-preserving handling.' }
$sourceMarkers = [regex]::Matches($sourceSuffix, '(?m)^[ \t]*<!-- entire-agent:(begin|end) -->[ \t]*\r?$')
for ($i = 0; $i -lt $sourceMarkers.Count; $i++) {
    $kind = if ($i % 2 -eq 0) { 'begin' } else { 'end' }
    if ($sourceMarkers[$i].Groups[1].Value -cne $kind) { throw 'The repository-managed markers are out of order.' }
}
if ($sourceMarkers.Count % 2 -ne 0) { throw 'The repository-managed block is not closed.' }

$hasCrLf = $previous.Contains([string]([char]13) + [char]10)
if ($hasCrLf -and $previous -match '(?<!\r)\n') { throw 'Mixed line endings need manual review.' }
if ($hasCrLf) {
    $approvedPrefix = $approvedPrefix.Replace([string][char]10, ([string][char]13 + [char]10))
    $master = $master.Replace([string][char]10, ([string][char]13 + [char]10))
}

$target = if ([string]::IsNullOrWhiteSpace($sourceSuffix)) { $master } else { $approvedPrefix + $sourceSuffix }
if ($hasBom) { $target = ([string][char]0xFEFF) + $target }
$targetBytes = $utf8.GetBytes($target)
$targetDigest = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($targetBytes))
$written = [Collections.Generic.List[string]]::new()
try {
    foreach ($path in $paths) {
        $written.Add($path)
        [IO.File]::WriteAllBytes($path, $targetBytes)
        if ((Get-FileHash -LiteralPath $path).Hash -cne $targetDigest) { throw "Instruction file content verification failed: $path" }
    }
} catch {
    foreach ($path in $written) { [IO.File]::WriteAllBytes($path, $priorBytes) }
    throw
}

[pscustomobject]@{
    Branch = $branch
    Base = $base
    Resolution = $session.resolution
    MasterSHA256 = $masterDigest
    BothFilesSHA256 = $targetDigest
    PreservedRepositorySuffixSHA256 = if ([string]::IsNullOrWhiteSpace($sourceSuffix)) { $null } else { [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($utf8.GetBytes($sourceSuffix))) }
    PreservedManagedBlocks = ($sourceMarkers.Count / 2)
} | ConvertTo-Json -Compress
